// simple memoize helper for non-signal code
export function memoizeLast<A, R>(fn: (a: A) => R): (a: A) => R {
  let lastArg: A, lastResult: R, has = false;
  return (a: A) => (has && a === lastArg ? lastResult : ((has = true), (lastArg = a), (lastResult = fn(a))));
}

